import * as React from "react"
import { Link } from "gatsby"
import { useLanguage } from "./language"
import { localizePost } from "./localize-post"

export const navigation = [
  ["/", "HOME"],
  ["/about", "ABOUT"],
  ["/works", "WORKS"],
  ["/contact", "CONTACT"],
  ["/blog", "BLOG"],
]

const Layout = ({
  location,
  children,
  showBottomNavigation = false,
  articleCategory,
  articlePosts = [],
}) => {
  const { locale, setLocale, t } = useLanguage()
  const [menuOpen, setMenuOpen] = React.useState(false)
  const [openPreviewId, setOpenPreviewId] = React.useState(null)
  const menuButton = React.useRef(null)
  React.useEffect(() => {
    setMenuOpen(false)
    setOpenPreviewId(null)
  }, [location.pathname])
  const closeOnEscape = event => {
    if (event.key === "Escape" && menuOpen) {
      setMenuOpen(false)
      menuButton.current?.focus()
    }
  }
  const positionIndexPreview = event => {
    const link = event.currentTarget
    setOpenPreviewId(link.dataset.previewId)
    const rect = link.getBoundingClientRect()
    link.style.setProperty("--preview-collapsed-width", `${rect.width}px`)
    link.style.setProperty(
      "--preview-top",
      `${Math.max(8, Math.min(rect.top, window.innerHeight - 100))}px`
    )
    link.style.setProperty("--preview-left", `${rect.left}px`)
    const preview = link.querySelector(".article-index-expanded")
    const context = document.createElement("canvas").getContext("2d")
    let contentWidth = rect.width
    if (preview && context) {
      const previewStyle = window.getComputedStyle(preview)
      const inset =
        parseFloat(previewStyle.paddingLeft) +
        parseFloat(previewStyle.paddingRight) +
        parseFloat(previewStyle.borderLeftWidth) +
        parseFloat(previewStyle.borderRightWidth)
      for (const row of preview.children) {
        const style = window.getComputedStyle(row)
        context.font = `${style.fontWeight} ${style.fontSize} ${style.fontFamily}`
        const spacing = parseFloat(style.letterSpacing) || 0
        const text = row.textContent || ""
        contentWidth = Math.max(
          contentWidth,
          context.measureText(text).width +
            Math.max(0, text.length - 1) * spacing +
            inset +
            2
        )
      }
    }
    link.style.setProperty(
      "--preview-width",
      `${Math.ceil(
        Math.min(contentWidth, 640, window.innerWidth - rect.left - 24)
      )}px`
    )
  }
  const isRootPath = location.pathname === `${__PATH_PREFIX__}/`

  return (
    <div
      className={`global-wrapper${articleCategory ? " has-article-index" : ""}`}
      data-is-root-path={isRootPath}
      data-page={
        location.pathname.replace(/\/+$/, "").split("/").pop() || "home"
      }
    >
      <a className="skip-link" href="#main-content">
        {t("本文へ移動", "Skip to content")}
      </a>
      <header className="global-header">
        <div className="header-inner">
          <Link
            className="site-brand"
            to="/"
            aria-label={t("tak. 7. ホーム", "tak. 7. Home")}
          >
            tak. 7.
          </Link>
          <div
            className="language-switch"
            role="group"
            aria-label={t("表示言語", "Language")}
          >
            <button
              type="button"
              lang="ja"
              aria-pressed={locale === "ja"}
              onClick={() => setLocale("ja")}
            >
              日本語
            </button>
            <span aria-hidden="true">/</span>
            <button
              type="button"
              lang="en"
              aria-pressed={locale === "en"}
              onClick={() => setLocale("en")}
            >
              EN
            </button>
          </div>
          <button
            ref={menuButton}
            onKeyDown={closeOnEscape}
            className="menu-toggle"
            type="button"
            aria-expanded={menuOpen}
            aria-controls="main-navigation"
            aria-label={
              menuOpen
                ? t("メニューを閉じる", "Close menu")
                : t("メニューを開く", "Open menu")
            }
            onClick={() => setMenuOpen(open => !open)}
          >
            <span className="menu-icon" aria-hidden="true">
              <span />
              <span />
              <span />
            </span>
            <span>MENU</span>
          </button>
          <nav
            id="main-navigation"
            className={menuOpen ? "site-nav is-open" : "site-nav"}
            aria-label={t("メインナビゲーション", "Main navigation")}
          >
            <ul className="ul-header">
              {navigation.map(([path, label]) => (
                <li className="heading-menu-li" key={path}>
                  <Link
                    className="heading-menu-a"
                    onKeyDown={closeOnEscape}
                    activeClassName="is-active"
                    to={path}
                    onClick={() => setMenuOpen(false)}
                  >
                    {label}
                    <span className="nav-arrow" aria-hidden="true">
                      ↗
                    </span>
                  </Link>
                </li>
              ))}
            </ul>
          </nav>
          <p className="sidebar-note">
            Architecture.
            <br />
            Spatial Cognition.
            <br />
            Navigation.
          </p>
        </div>
      </header>
      {articleCategory && (
        <nav
          className="article-index"
          aria-label={
            articleCategory === "news"
              ? t("ニュース記事一覧", "News articles")
              : t("ブログ記事一覧", "Blog articles")
          }
        >
          <p className="article-index-heading">
            {articleCategory === "news" ? "News" : "Blog"}
            <span>{articlePosts.length}</span>
          </p>
          <ol>
            {articlePosts
              .map(post => localizePost(post, locale))
              .map(post => (
                <li key={post.id}>
                  <Link
                    to={post.fields.slug}
                    activeClassName="is-current"
                    data-preview-id={post.id}
                    className={
                      openPreviewId === post.id ? "is-preview-open" : undefined
                    }
                    onClick={() => setOpenPreviewId(null)}
                    onMouseLeave={() => setOpenPreviewId(null)}
                    onBlur={() => setOpenPreviewId(null)}
                    onMouseEnter={positionIndexPreview}
                    onFocus={positionIndexPreview}
                  >
                    <time dateTime={post.frontmatter.rawDate}>
                      {post.frontmatter.date}
                    </time>
                    <span className="article-index-title">
                      {post.frontmatter.title}
                    </span>
                    <span className="article-index-excerpt">
                      {post.frontmatter.description || post.excerpt}
                    </span>
                    <span className="article-index-expanded" aria-hidden="true">
                      <span className="article-index-date">
                        {post.frontmatter.date}
                      </span>
                      <span className="article-index-title">
                        {post.frontmatter.title}
                      </span>
                      <span className="article-index-excerpt">
                        {post.frontmatter.description || post.excerpt}
                      </span>
                    </span>
                  </Link>
                </li>
              ))}
          </ol>
        </nav>
      )}
      <main
        id="main-content"
        data-article={showBottomNavigation}
        data-compact-mobile={/\/(about|works|contact)\/?$/.test(
          location.pathname
        )}
      >
        {children}
        {(showBottomNavigation ||
          isRootPath ||
          /\/(about|works|blog|contact)\/?$/.test(location.pathname)) && (
          <nav
            className="page-bottom-nav"
            aria-label={t("ページ下部のメニュー", "Footer navigation")}
          >
            <ul>
              {navigation.map(([path, label]) => (
                <li key={path}>
                  <Link to={path} activeClassName="is-active">
                    {label}
                  </Link>
                </li>
              ))}
            </ul>
          </nav>
        )}
      </main>
      <footer className="copyright-footer">
        Copyright © 2025 Nanahara Takanori.
      </footer>
    </div>
  )
}

export default Layout
